import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.Boholvbs.js";const r="/docs/assets/create-discovery.Be7OcPID.png",i="/docs/assets/discovery-stories.9y_fZ-Iq.png",n="/docs/assets/discovery-maps.BYsMCfEk.png",c="/docs/assets/discovery-sharing.BFqeukUZ.png",f=JSON.parse('{"title":"Discovery","description":"","frontmatter":{},"headers":[],"relativePath":"discovery.md","filePath":"discovery.md"}'),l={name:"discovery.md"};function h(d,e,p,y,m,g){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;Discovery&quot;">​</a></h1><p>Discovery page is an interactive map where the user can add layers, see stories based on published geolocated posts and share it&#39;s own customized map with others. Discovery page has a left sidebar with two tabs: <strong>STORIES</strong> and <strong>MAP LAYERS</strong>. You can hide this sidebar by clicking on the two left arrow icon, at the right of the sidebar.</p><h2 id="how-to-create-a-discovery-page" tabindex="-1">How to create a Discovery page <a class="header-anchor" href="#how-to-create-a-discovery-page" aria-label="Permalink to &quot;How to create a Discovery page&quot;">​</a></h2><p>To create a discovery page, you only need to create a normal Wordpress page and select <code>Discovery</code> in the Model settings.</p><p><img src="'+r+'" alt="Create Discovery"></p><p>Any content that is added to that page will be ignored and the page will only display the Discovery feature.</p><h2 id="stories" tabindex="-1">Stories <a class="header-anchor" href="#stories" aria-label="Permalink to &quot;Stories&quot;">​</a></h2><p>Stories are the geolocated posts that are shown on the map. Clicking on <code>SHOW FILTERS</code> allows you to filter these stories by date and tags. Below these filters, a list with the result will be shown. Each result is also a link to the story itself. Also, hovering the mouse on a map marker will highlight the related story int the left sidebar. In the same way, hovering the mouse on <code>View in map</code> text will highlight the map marker realted to it.</p><p><img src="'+i+'" alt="Discovery Stories"></p><h2 id="map-layers" tabindex="-1">Map Layers <a class="header-anchor" href="#map-layers" aria-label="Permalink to &quot;Map Layers&quot;">​</a></h2><p>In Map Layers tab you can search for maps and apply its layers to your interactive map. You can filter maps by name and select different layers from different maps. After selecting at least one layer from a map, you can click on <code>Clear</code> to remove all the selected layers from this map before applying the changes. It is also possible to add all layers from a map with one single click when selecting <strong>Apply</strong> next to a map result.</p><p>At the top of the sidebar, you will be able to see all the selected layers, allowing you to remove some of them. These layers always have a drag and drop function, so that you can re-order them. After reviewing these layers, you need to click on <code>Apply changes</code> to show them on discovery map.</p><p><img src="'+n+'" alt="Discovery Maps"></p><h2 id="sharing" tabindex="-1">Sharing <a class="header-anchor" href="#sharing" aria-label="Permalink to &quot;Sharing&quot;">​</a></h2><p>At the right-top side of the map, there&#39;s a share button where you can share the content on <strong>Twitter</strong>, <strong>Facebook</strong>, <strong>E-mail</strong> or even generate a custom link for your map. Also, clicking on <code>embed</code> makes a popup appears with a HTML code to have your custom map embed into another website.</p><p><img src="'+c+'" alt="Discovery Sharing"></p>',16)])])}const v=a(l,[["render",h]]);export{f as __pageData,v as default};
